import React, { useState } from 'react';
import { motion } from 'framer-motion';
import './EnhancedExport.css';

function EnhancedExport({ data, selectedDistrict, businessCategories }) {
  const [exportFormat, setExportFormat] = useState('csv');
  const [isExporting, setIsExporting] = useState(false);
  const [showOptions, setShowOptions] = useState(false);

  const handleExport = async () => {
    console.log('Export clicked. Format:', exportFormat);
    console.log('Data available:', data);
    console.log('Data length:', data?.length);
    console.log('Business categories:', businessCategories);
    console.log('Selected district:', selectedDistrict);

    setIsExporting(true);

    try {
      switch (exportFormat) {
        case 'csv':
          await exportToCSV();
          break;
        case 'excel':
          await exportToExcel();
          break;
        case 'pdf':
          await exportToPDF();
          break;
        case 'json':
          await exportToJSON();
          break;
        default:
          await exportToCSV();
      }
    } catch (error) {
      console.error('Export failed:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const exportToCSV = async () => {
    if (!data || data.length === 0) {
      console.warn('No data available for CSV export');
      return;
    }

    try {
      let headers = ['Pincode', 'Area', 'District', 'Population', 'Growth Rate', 'Income Level', 'Urban Development'];

      businessCategories.forEach(cat => {
        headers.push(`${cat.name} Competitors`);
        headers.push(`${cat.name} Demand Score`);
        headers.push(`${cat.name} Market Gap Score`);
      });

      let csvRows = [headers.join(',')];

      data.forEach(pincode => {
        const row = [
          pincode.pincode,
          pincode.area,
          pincode.district,
          pincode.population,
          pincode.populationGrowth,
          pincode.incomeLevel,
          pincode.urbanDevelopment
        ];

        businessCategories.forEach(cat => {
          row.push((pincode.competitors && pincode.competitors[cat.name]) || 0);
          row.push((pincode.demandScores && pincode.demandScores[cat.name]) || 0);
          row.push((pincode.marketGapScores && pincode.marketGapScores[cat.name]) || 0);
        });

        csvRows.push(row.join(','));
      });

      let csvContent = csvRows.join('\n');
      downloadFile(csvContent, `market-gap-analysis-${selectedDistrict}.csv`, 'text/csv');
    } catch (error) {
      console.error('CSV export error:', error);
    }
  };

  const exportToExcel = async () => {
    console.log('exportToExcel called');
    console.log('Data:', data);
    console.log('Business categories:', businessCategories);

    if (!data || data.length === 0) {
      console.warn('No data available for Excel export');
      alert('No data available to export');
      return;
    }

    if (!businessCategories || businessCategories.length === 0) {
      console.warn('No business categories available for Excel export');
      alert('No business categories available to export');
      return;
    }

    try {
      let headers = ['Pincode', 'Area', 'District', 'Population', 'Growth Rate', 'Income Level', 'Urban Development'];

      businessCategories.forEach(cat => {
        headers.push(`${cat.name} Competitors`);
        headers.push(`${cat.name} Demand Score`);
        headers.push(`${cat.name} Market Gap Score`);
      });

      let excelRows = [headers.join('\t')];

      data.forEach(pincode => {
        const row = [
          pincode.pincode,
          pincode.area,
          pincode.district,
          pincode.population,
          pincode.populationGrowth,
          pincode.incomeLevel,
          pincode.urbanDevelopment
        ];

        businessCategories.forEach(cat => {
          row.push((pincode.competitors && pincode.competitors[cat.name]) || 0);
          row.push((pincode.demandScores && pincode.demandScores[cat.name]) || 0);
          row.push((pincode.marketGapScores && pincode.marketGapScores[cat.name]) || 0);
        });

        excelRows.push(row.join('\t'));
      });

      let excelContent = excelRows.join('\n');
      console.log('Excel content generated, calling downloadFile');
      downloadFile(excelContent, `market-gap-analysis-${selectedDistrict}.xls`, 'application/vnd.ms-excel');
      console.log('Excel download completed');
    } catch (error) {
      console.error('Excel export error:', error);
    }
  };

  const exportToPDF = async () => {
    console.log('exportToPDF (Report) called');
    console.log('Data:', data);
    console.log('Business categories:', businessCategories);

    if (!data || data.length === 0) {
      console.warn('No data available for Report export');
      alert('No data available to export');
      return;
    }

    if (!businessCategories || businessCategories.length === 0) {
      console.warn('No business categories available for Report export');
      alert('No business categories available to export');
      return;
    }

    try {
      let pdfRows = [
        'MARKET GAP ANALYSIS REPORT',
        `District: ${selectedDistrict}`,
        `Generated: ${new Date().toLocaleDateString()}`,
        '',
        'EXECUTIVE SUMMARY',
        '================',
        `Total Pincodes Analyzed: ${data.length}`,
        `Total Population: ${data.reduce((sum, p) => sum + p.population, 0).toLocaleString()}`,
        `Average Growth Rate: ${(data.reduce((sum, p) => sum + p.populationGrowth, 0) / data.length).toFixed(2)}%`,
        '',
        'DETAILED ANALYSIS',
        '================',
        ''
      ];

      data.forEach((pincode, index) => {
        pdfRows.push(`${index + 1}. ${pincode.area} (${pincode.pincode})`);
        pdfRows.push(`   Population: ${pincode.population.toLocaleString()}`);
        pdfRows.push(`   Growth Rate: ${pincode.populationGrowth}%`);
        pdfRows.push(`   Income Level: ${pincode.incomeLevel}`);
        pdfRows.push(`   Urban Development: ${pincode.urbanDevelopment}`);
        pdfRows.push('');
        pdfRows.push('   Category Analysis:');

        businessCategories.forEach(cat => {
          pdfRows.push(`   ${cat.name}: Gap=${(pincode.marketGapScores && pincode.marketGapScores[cat.name]) || 0}, Demand=${(pincode.demandScores && pincode.demandScores[cat.name]) || 0}, Competitors=${(pincode.competitors && pincode.competitors[cat.name]) || 0}`);
        });
        pdfRows.push('');
      });

      let pdfContent = pdfRows.join('\n');
      console.log('Report content generated, calling downloadFile');
      downloadFile(pdfContent, `market-gap-report-${selectedDistrict}.txt`, 'text/plain');
      console.log('Report download completed');
    } catch (error) {
      console.error('Report export error:', error);
    }
  };

  const exportToJSON = async () => {
    if (!data || data.length === 0) {
      console.warn('No data available for JSON export');
      return;
    }

    try {
      const jsonData = {
        metadata: {
          district: selectedDistrict,
          exportDate: new Date().toISOString(),
          totalPincodes: data.length,
          businessCategories: businessCategories.map(cat => cat.name)
        },
        data: data.map(pincode => ({
          pincode: pincode.pincode,
          area: pincode.area,
          district: pincode.district,
          population: pincode.population,
          populationGrowth: pincode.populationGrowth,
          incomeLevel: pincode.incomeLevel,
          urbanDevelopment: pincode.urbanDevelopment,
          competitors: pincode.competitors,
          demandScores: pincode.demandScores,
          marketGapScores: pincode.marketGapScores
        }))
      };

      const jsonContent = JSON.stringify(jsonData, null, 2);
      downloadFile(jsonContent, `market-gap-analysis-${selectedDistrict}.json`, 'application/json');
    } catch (error) {
      console.error('JSON export error:', error);
    }
  };

  const downloadFile = (content, filename, mimeType) => {
    try {
      const blob = new Blob([content], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      setTimeout(() => {
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      }, 100);
    } catch (error) {
      console.error('Download failed:', error);
    }
  };

  const formatOptions = [
    { value: 'csv', label: 'CSV', icon: '📊', description: 'Comma-separated values' },
    { value: 'excel', label: 'Excel', icon: '📈', description: 'Tab-separated spreadsheet' },
    { value: 'pdf', label: 'Report', icon: '📄', description: 'Formatted text report' },
    { value: 'json', label: 'JSON', icon: '🔧', description: 'Structured data format' }
  ];

  return (
    <div className="enhanced-export">
      <div className="export-header">
        <h3>📥 Enhanced Export</h3>
        <button 
          className="options-toggle"
          onClick={() => setShowOptions(!showOptions)}
        >
          {showOptions ? '▼' : '▶'} Options
        </button>
      </div>

      <motion.div 
        className="export-options"
        initial={{ height: 'auto' }}
        animate={{ height: showOptions ? 'auto' : '0px' }}
        transition={{ duration: 0.3 }}
        style={{ overflow: 'hidden' }}
      >
        <div className="format-selector">
          <h4>Select Format</h4>
          <div className="format-grid">
            {formatOptions.map(format => (
              <div
                key={format.value}
                className={`format-card ${exportFormat === format.value ? 'selected' : ''}`}
                onClick={() => {
                  setExportFormat(format.value);
                  // Trigger export immediately when card is clicked
                  setTimeout(handleExport, 0);
                }}
              >
                <span className="format-icon">{format.icon}</span>
                <span className="format-label">{format.label}</span>
                <span className="format-description">{format.description}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="export-summary">
          <h4>Export Summary</h4>
          <div className="summary-grid">
            <div className="summary-item">
              <span className="summary-label">District</span>
              <span className="summary-value">{selectedDistrict}</span>
            </div>
            <div className="summary-item">
              <span className="summary-label">Pincodes</span>
              <span className="summary-value">{data?.length || 0}</span>
            </div>
            <div className="summary-item">
              <span className="summary-label">Categories</span>
              <span className="summary-value">{businessCategories?.length || 0}</span>
            </div>
            <div className="summary-item">
              <span className="summary-label">Format</span>
              <span className="summary-value">{exportFormat.toUpperCase()}</span>
            </div>
          </div>
        </div>
      </motion.div>

      <button 
        className="export-button"
        onClick={handleExport}
        disabled={isExporting || !data || data.length === 0}
      >
        {isExporting ? 'Exporting...' : `Export as ${exportFormat.toUpperCase()}`}
      </button>
    </div>
  );
}

export default EnhancedExport;
